 "new_string": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find monochromatic diagonal runs of length >= 2 and extend each run
    # backwards, opposite its direction of travel, to the grid boundary.
    for color in set(v for row in grid for v in row):
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for dr, dc in ((1, 1), (1, -1)):
            runs = []
            for r, c in pts:
                prev = (r-dr, c-dc)
                if prev in pts:
                    continue
                run = [(r, c)]
                nr, nc = r+dr, c+dc
                while (nr, nc) in pts:
                    run.append((nr, nc))
                    nr += dr
                    nc += dc
                if len(run) >= 2:
                    runs.append(run)
            for run in runs:
                r, c = run[0]
                r, c = r-dr, c-dc
                while 0 <= r < h and 0 <= c < w:
                    if out[r][c] != grid[0][0]:
                        break
                    out[r][c] = color
                    r, c = r-dr, c-dc
    return out
